const cvt = new DataView(new ArrayBuffer(8));
function fromWords(hi: number, lo: number): number {
  cvt.setUint32(0, hi >>> 0);
  cvt.setUint32(4, lo >>> 0);
  return cvt.getFloat64(0);
}
function hiWord(x: number): number {
  cvt.setFloat64(0, x);
  return cvt.getUint32(0);
}
function loWord(x: number): number {
  cvt.setFloat64(0, x);
  return cvt.getUint32(4);
}
/** The double whose bit pattern is x's plus e << 52 (an exponent shift; the result stays normal). */
function addExp(x: number, e: number): number {
  cvt.setFloat64(0, x);
  cvt.setUint32(0, (cvt.getUint32(0) + (e << 20)) >>> 0);
  return cvt.getFloat64(0);
}

const EXP_TH = new Float64Array(128);
const EXP_TL = new Float64Array(128);
for (let j = 0; j < 128; j++) {
  EXP_TH[j] = fromWords(EXP_T[4 * j], EXP_T[4 * j + 1]);
  EXP_TL[j] = fromWords(EXP_T[4 * j + 2], EXP_T[4 * j + 3]);
}
const LOG_C = new Float64Array(129);
const LOG_H = new Float64Array(129);
const LOG_L = new Float64Array(129);
for (let j = 0; j < 129; j++) {
  LOG_C[j] = fromWords(LOG_T[6 * j], LOG_T[6 * j + 1]);
  LOG_H[j] = fromWords(LOG_T[6 * j + 2], LOG_T[6 * j + 3]);
  LOG_L[j] = fromWords(LOG_T[6 * j + 4], LOG_T[6 * j + 5]);
}

// ------------------------------------------------------------------ exp

const E_C = fromWords(0x40671547, 0x652b82fe); // 128 / ln 2
const E_CL = fromWords(0x3ce777d0, 0xffda0d24);
const E_16 = fromWords(0x408ef158, 0x4af17ecd);
const E_17 = fromWords(0xc0513b4d, 0x4879e55e);
const E_18 = fromWords(0x4114ffde, 0x7cc02cf4);
const E_19 = fromWords(0x4118b31b, 0x87eb8904);
const E_20 = fromWords(0x3d25e522, 0x72e0eaec);
const DBL_MAX = fromWords(0x7fefffff, 0xffffffff);
const TINY = fromWords(0x00100000, 0); // 2^-1022

/** macOS libm exp (0x18fed6380). */
export function exp(x: number): number {
  const hi = hiWord(x), lo = loWord(x);
  if (hi > 0x40862e42 || (hi === 0x40862e42 && lo >= 0xfefa39f0)) {
    // unsigned bits >= 709.78..: only negative x above -745.25 (signed bits below 0xc0874a00..) continue
    if (!(hi >= 0x80000000 && hi < 0xc0874a00)) {
      if (!(x < 0)) return x * DBL_MAX;
      return 0;
    }
  }
  let d1 = x * E_C;
  const k = Math.floor(d1);
  let d2 = d1 - k;
  d1 = fma64(-x, E_C, d1); // fmsub: d1 - x*C
  const d4 = fma64(x, E_CL, -d1); // fnmsub: x*Clo - d1
  const j = k & 127;
  const th = EXP_TH[j];
  const d16 = d2 + E_16;
  d1 = EXP_TL[j] + d4;
  const d17 = d2 + E_17;
  d2 = d2 + d1;
  const d18 = fma64(d2, d16, E_18);
  const d19 = fma64(d2, d17, E_19);
  d2 = d2 * E_20;
  d2 = d2 * d18;
  d2 = d2 * d19;
  const e = k >> 7;
  if (e + 0x3fe >= 0) return addExp(fma64(d2, th, th), e);
  // results below the smallest normal: round once into the subnormal range
  const d0 = addExp(th, e + 0x3fe);
  const d3 = d0 + 1;
  let t = d3 - 1;
  t = d0 - t;
  t = fma64(d0, d2, t);
  return (d3 + t - 1) * TINY;
}

// ------------------------------------------------------------------ log

const L_C0 = fromWords(0xbfc7b47c, 0x30037039);
const L_C1 = fromWords(0x3fc24944, 0x9239443d);
const L_C2 = fromWords(0x3ff9de61, 0x616cdf2b);
const L_C3 = fromWords(0x3ff609d1, 0x4c7ee9be);
const L_C4 = fromWords(0x3ffab7d4, 0xf0547db7);
const L_C5 = fromWords(0xbff3f6ab, 0x6ec10818);
const LN2_HI = fromWords(0x3fe62e42, 0xf0000000);
const LN2_LO = fromWords(0x3e5df473, 0xde6af279);

/** macOS libm log (0x18fed6180). */
export function log(x: number): number {
  let hi = hiWord(x);
  let lo = loWord(x);
  // (bits - 2^52) >= 0x7fe0000000000000 unsigned: zero, subnormal, negative, inf, NaN
  const t = (hi - 0x00100000) >>> 0;
  if (t >= 0x7fe00000) {
    if (x !== x) return x;
    if (x === 0) return -Infinity;
    if (x < 0) return NaN;
    if (x === Infinity) return x;
    // subnormal: 1.m - 1 = m 2^-52 (exact), then exponent - 1022
    const d = fromWords(0x3ff00000 | (hi & 0x000fffff), lo) - 1;
    hi = (hiWord(d) - 0x3fe00000) | 0;
    lo = loWord(d);
  }
  // e = (bits + 0xc018100000000000) >> 52 (arithmetic): exponent relative to 0.748
  const e = ((hi - 0x3fe7f000) | 0) >> 20;
  const mh = hi & 0x000fffff;
  // index = (mantissa + 2^44) >> 45
  const idx = ((mh + 0x1000) >>> 13);
  const m = fromWords(0x3ff00000 | mh, lo);
  const c = LOG_C[idx], lh = LOG_H[idx], ll = LOG_L[idx];
  const r = fma64(m, c, -1);
  const d16 = fma64(r, L_C1, L_C0);
  const d19 = r + L_C3;
  const d21 = r + L_C5;
  let d4 = r * r;
  const d18 = fma64(r, d19, L_C2);
  const d20 = fma64(r, d21, L_C4);
  d4 = d4 * d16;
  d4 = d4 * d18;
  d4 = d4 * d20;
  if (e !== 0) {
    const de = e;
    let d2 = fma64(de, LN2_LO, ll);
    const d3 = fma64(de, LN2_HI, lh);
    d2 = d2 + d4;
    return d3 + (r + d2);
  }
  const d5 = c * m;
  const d6 = d5 - 1;
  const d5e = fma64(c, m, -d5); // fnmsub: c*m - d5
  // d1 = d6 with the low 27 bits of the mantissa cleared
  const d1 = fromWords(hiWord(d6), loWord(d6) & 0xf8000000);
  let d2 = d6 - d1;
  d2 = d5e + d2;
  const d0 = d1 + lh;
  d2 = d2 + ll;
  d2 = d2 + d4;
  return d0 + d2;
}

// ------------------------------------------------------------------ sin / cos

const PIO4 = fromWords(0x3fe921fb, 0x54442d18);
const MEDIUM = fromWords(0x41200001, 0x3be57a40); // 524288.61698514968
const TWO_OVER_PI = fromWords(0x3fe45f30, 0x6dc9c883);
const P1 = fromWords(0x3ff921fb, 0x54440000);
const P2 = fromWords(0x3d868c23, 0x4c4c0000);
const P3 = fromWords(0x3b298a2e, 0x03707345);
const S0 = fromWords(0x3de5d8fd, 0x1fd19ccd);
const S1 = fromWords(0xbe5ae5e5, 0xa9291f5d);
const S2 = fromWords(0x3ec71de3, 0x567d48a1);
const S3 = fromWords(0xbf2a01a0, 0x19bfdf03);
const S4 = fromWords(0x3f811111, 0x1110f7d0);
const S5 = fromWords(0xbfc55555, 0x55555548);
const Q0 = fromWords(0xbda8fa49, 0xa0861a9b);
const Q1 = fromWords(0x3e21ee9d, 0x7b4e3f05);
const Q2 = fromWords(0xbe927e4f, 0x7eac4bc6);
const Q3 = fromWords(0x3efa01a0, 0x19c844f5);
const Q4 = fromWords(0xbf56c16c, 0x16c14f91);
const Q5 = fromWords(0x3fa55555, 0x5555554b);
const Q6 = fromWords(0xbfe00000, 0x00000000);

/** sin kernel 0x18fed6068 on r = (rh, rl); flip negates the result. */
function sinK(rh: number, rl: number, flip: boolean): number {
  let d0 = rh + rl;
  const z = d0 * d0;
  let p = fma64(z, S0, S1);
  p = fma64(z, p, S2);
  p = fma64(z, p, S3);
  p = fma64(z, p, S4);
  p = fma64(z, p, S5);
  d0 = fma64(d0, z * p, rl);
  d0 = d0 + rh;
  return flip ? -d0 : d0;
}

/** cos kernel 0x18fed6170 on r = (rh, rl). */
function cosK(rh: number, rl: number, flip: boolean): number {
  let t = rh * rl;
  t = t + t;
  const z = fma64(rh, rh, t);
  let q = fma64(z, Q0, Q1);
  q = fma64(z, q, Q2);
  q = fma64(z, q, Q3);
  q = fma64(z, q, Q4);
  q = fma64(z, q, Q5);
  q = fma64(z, q, Q6);
  const d0 = fma64(z, q, 1);
  return flip ? -d0 : d0;
}

/** frintn / fcvtns: round half to even. */
function rne(x: number): number {
  const r = Math.round(x);
  return r - x === 0.5 && r % 2 !== 0 ? r - 1 : r;
}

// Cody-Waite reduction results
let redH = 0;
let redL = 0;
function reduce(x: number, k: number): void {
  const d5 = k * P1;
  const d1 = k * P2;
  const d7 = k * P3;
  const d0 = x - d5;
  const d6 = d0 - d1;
  let d2 = d0 - d6;
  d2 = d2 - d1;
  redH = d6;
  redL = d2 - d7;
}

/** macOS libm sin (0x18fed5968). */
export function sin(x: number): number {
  if (x === 0) return x;
  const a = Math.abs(x);
  if (a <= PIO4) return sinK(0, x, false); // fast path: d6 = 0, d7 = x
  if (!(a < MEDIUM)) return x !== x ? x : Math.sin(x);
  const k = rne(x * TWO_OVER_PI);
  reduce(x, k);
  const flip = (k & 2) !== 0;
  return (k & 1) !== 0 ? cosK(redH, redL, flip) : sinK(redH, redL, flip);
}

/** macOS libm cos (0x18fed5ad4). */
export function cos(x0: number): number {
  const x = Math.abs(x0);
  if (x <= PIO4) return cosK(x, 0, false);
  if (!(x < MEDIUM)) return x !== x ? x : Math.cos(x0);
  const k = rne(x * TWO_OVER_PI);
  reduce(x, k);
  const flip = ((k ^ (k >>> 1)) & 1) !== 0;
  return (k & 1) === 0 ? cosK(redH, redL, flip) : sinK(redH, redL, flip);
}
